const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const needlesPoint = ee.Geometry.Point([-114.614, 34.848]);
    const phoenixPoint = ee.Geometry.Point([-112.074, 33.448]);
    // Widen date range to increase chance of getting a Landsat image
    const dateRange = ee.DateRange('2017-06-18', '2017-06-25');

    // 2. Data Acquisition & Processing Function
    const getLST = function(geometry, locationName) {
        let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterBounds(geometry)
            .filterDate(dateRange)
            .select(['ST_B10', 'QA_PIXEL']);

        // Function to mask clouds based on the QA_PIXEL band
        const maskL8sr = function(image) {
            const qa = image.select('QA_PIXEL');
            // Bits 3 and 5 are cloud shadow and cloud, respectively.
            const cloudShadowBitMask = (1 << 3);
            const cloudsBitMask = (1 << 5);
            const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                           .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
            return image.updateMask(mask);
        };

        const maskedCollection = collection.map(maskL8sr);
        const image = maskedCollection.mosaic(); // Use mosaic for best available pixel

        // Check for valid image data after mosaic
        const count = image.select('ST_B10').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: 30
        }).get('ST_B10').getInfo();

        if (count === 0) {
            return {
                temp: null,
                count: 0,
                status: 'C2'
            };
        }

        // Apply scaling factors and convert from Kelvin to Celsius
        const scaledTemp = image.select('ST_B10').multiply(0.00341802).add(149.0).subtract(273.15);

        const tempResult = scaledTemp.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geometry,
            scale: 30
        }).get('ST_B10').getInfo();

        return {
            temp: tempResult,
            count: count,
            status: 'OK'
        };
    };

    // Check initial collection sizes before processing
    const needlesColSize = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(needlesPoint).filterDate(dateRange).size().getInfo();
    const phoenixColSize = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(phoenixPoint).filterDate(dateRange).size().getInfo();

    if (needlesColSize === 0 || phoenixColSize === 0) {
        console.log(`Needles Image Count: ${needlesColSize}`);
        console.log(`Phoenix Image Count: ${phoenixColSize}`);
        console.log("No images found for one or both locations in the specified date range.");
        console.log("C1");
        return;
    }

    // 3. Calculation
    const needlesData = getLST(needlesPoint, 'Needles');
    const phoenixData = getLST(phoenixPoint, 'Phoenix');

    // 4. Validation & Final Answer
    if (needlesData.status === 'C2' || phoenixData.status === 'C2') {
        console.log(`Needles Valid Pixels: ${needlesData.count}`);
        console.log(`Phoenix Valid Pixels: ${phoenixData.count}`);
        console.log("No valid (non-cloud) pixels found after masking for one or both locations.");
        console.log("C2");
        return;
    }

    const needlesTemp = needlesData.temp;
    const phoenixTemp = phoenixData.temp;

    console.log(`Needles, CA LST: ${needlesTemp !== null ? needlesTemp.toFixed(2) : 'N/A'} C`);
    console.log(`Phoenix, AZ LST: ${phoenixTemp !== null ? phoenixTemp.toFixed(2) : 'N/A'} C`);

    if (needlesTemp === null || phoenixTemp === null) {
        console.log("Calculation failed, temperature result is null.");
        console.log("C3");
        return;
    }

    if (needlesTemp > phoenixTemp) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
